<?php $items = array(); foreach ( preg_split( '/\r?\n/', (string) get_theme_mod( 'kimpu_statistics_items', '' ) ) as $line ) { $parts = array_map( 'trim', explode( '|', $line ) ); if ( ! empty( $parts[0] ) && isset( $parts[1] ) ) { $items[] = array( 'label' => $parts[0], 'value' => $parts[1], 'prefix' => isset( $parts[2] ) ? $parts[2] : '', 'suffix' => isset( $parts[3] ) ? $parts[3] : '' ); } } ?><section class="section <?php echo esc_attr( kimpu_homepage_section_classes( 'statistics' ) ); ?>" id="statistics"><div class="container"><?php kimpu_homepage_section_header( 'statistics' ); ?><?php if ( $items ) : ?><div class="statistics-grid statistics-columns-<?php echo esc_attr( 'four' === kimpu_homepage_section_value( 'statistics', 'layout', 'four' ) ? '4' : '3' ); ?>"><?php foreach ( $items as $item ) : ?><div class="statistic"><strong><?php echo esc_html( $item['prefix'] . $item['value'] . $item['suffix'] ); ?></strong><span><?php echo esc_html( $item['label'] ); ?></span></div><?php endforeach; ?></div><?php else : ?><p class="empty-state"><?php esc_html_e( 'Add statistics in the Homepage Builder using Label|Value|Prefix|Suffix.', 'kimpu-multipurpose' ); ?></p><?php endif; ?></div></section>
